          const categoryRecord = category as Record<string, unknown>;
          const name = typeof categoryRecord.name === 'string' ? categoryRecord.name : '';
          const slug = typeof categoryRecord.slug === 'string' ? categoryRecord.slug : '';
          if (name && slug) {
            acc.push({ name, slug });
